/bin/bash -lc "python - <<'PY'
import numpy as np
from scipy import ndimage as nd
f=np.load('source_pixels.npz')['rgb'];
for t in range(0,32):
 a=f[t].astype(float);r,g,b=a.transpose(2,0,1);m=(r-g>32)&(r>b*1.2);m[:,:116]=False;m[:,141:]=False
 lab,n=nd.label(m)
 c=[]
 for i,s in enumerate(nd.find_objects(lab)):
  z=lab[s]==i+1
  if z.sum()>12:
   yy,xx=np.where(z);c.append(((s[1].start,s[0].start,s[1].stop,s[0].stop),len(xx),round(xx.mean()+s[1].start,2),round(yy.mean()+s[0].start,2)))
 print(t,c)
for t in [0,3,6,9,12,15,18,27]:
 a=f[t]; print('\\n',t)
 for y in range(0,98):
  if (t==0 and y<32) or (t==3 and 20<y<65) or (t>=6 and y>49):
   s=''
   for x in range(112,144):
    r,g,b=map(float,a[y,x]);
    if r-g>32:c='R' if r>130 else 'r'
    elif min(r,g,b)>220:c='W'
    elif min(r,g,b)>175 and max(r,g,b)-min(r,g,b)<30:c='w'
    elif r<110 and g<115:c='#'
    elif g-r>15:c='.'
    elif r-g>10:c='o'
    else:c='+'
    s+=c
   print(f'{y:2d} '+s)
PY"
